import data.glitch_lib

# Define weak encryption patterns (strings to match against)
weak_algorithms := {"DES", "3DES", "RC4", "MD5", "SHA1", "SSLv2", "SSLv3", "TLS 1.0", "TLS 1.1", "AES-128", "RSA-1024"}
key_length_patterns := {"key_length", "key_size", "key_bits"}
encryption_attributes := {"algorithm", "cipher", "encryption_type", "crypto_method", "ssl_version", "tls_version", "protocol_version", "cipher_suites"}

# Check if a string value matches any weak algorithm pattern
check_weak_algorithm(value) {
    value.ir_type == "String"
    some weak_alg in weak_algorithms
    regex.match(sprintf("(?i).*%s.*", [weak_alg]), value.value)
}

# Check if key length is insufficient (e.g., less than 2048 for RSA)
check_insufficient_key_length(value) {
    value.ir_type == "String"
    regex.match("(?i).*key_?(size|length|bits)?.*<(?:1024|2048|256)", value.value)
} else {
    value.ir_type == "Integer"
    value.value < 2048
}

# Check for weak encryption configuration
check_weak_encryption_config(attr) {
    attr.ir_type == "Attribute"
    attr.name in encryption_attributes
    check_weak_algorithm(attr.value)
} else {
    attr.ir_type == "Attribute"
    attr.name in key_length_patterns
    check_insufficient_key_length(attr.value)
}

# Main detection rule for CWE-326 (Inadequate Encryption Strength)
